    test('canShow is false and energy effect enabled', () => {
    assertFalse(!!app.shadowRoot.querySelector('#searchbox'));
  });

    test('canShow is true and energy effect disabled', () => {
    assertFalse(!!app.shadowRoot.querySelector('#searchbox'));
  });

    test('canShow is false and energy effect disabled', () => {
    assertFalse(!!app.shadowRoot.querySelector('#searchbox'));
  });
  });

  suite('LimitingDisabled', () => {
    suiteSetup(() => {
      loadTimeData.overrideValues({
        ntpRealboxNextEnabled: true,
        ntpNextFeaturesEnabled: true,
        actionChipsEnabled: true,
        contextMenuAnimationLimitingEnabled: false,
      });
