      hasError: true,
      statusAction: StatusAction.CONFIRM_SYNC_SETTINGS,
    });
    await microtasksFinished();
    assertFalse(syncSection.hidden);
  });

  test('SyncSectionLayout_BookmarksLimitError', async function() {
